  using(var shade=new SolidBrush(Color.FromArgb(85,5,18,23)))g.FillRectangle(shade,0,0,area,Height);int fogY=Run.scoutRow>=9?0:Position(Run.nodes.First(n=>n.row==Run.scoutRow)).Y-22;using(var fog=new SolidBrush(Color.FromArgb(155,8,22,35)))if(fogY>0)g.FillRectangle(fog,0,0,area,fogY);for(int x=0;x<area;x+=24)if(fogY>0)using(var ink=new SolidBrush(Color.FromArgb(110+(x/24%3)*15,14,38,48)))g.FillRectangle(ink,x,fogY-10-(x/24%3)*8,24,26);
