public sealed class WoodlandCrossfade:Control {
 readonly Timer timer=new Timer{Interval=16};readonly Stopwatch time=new Stopwatch();public Bitmap Before,After;public Action Completed;public WoodlandCrossfade(){DoubleBuffered=true;SetStyle(ControlStyles.Opaque|ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint,true);timer.Tick+=(s,e)=>{Invalidate();if(time.ElapsedMilliseconds>=280){timer.Stop();if(Completed!=null)Completed();}};}
 public void Start(){time.Restart();timer.Start();}protected override void OnPaint(PaintEventArgs e){if(After!=null)e.Graphics.DrawImage(After,ClientRectangle);else e.Graphics.Clear(Color.FromArgb(14,32,35));if(Before!=null){float alpha=After==null?1:Math.Max(0,1-time.ElapsedMilliseconds/280f);using(var attr=new System.Drawing.Imaging.ImageAttributes()){var matrix=new System.Drawing.Imaging.ColorMatrix();matrix.Matrix33=alpha;attr.SetColorMatrix(matrix);e.Graphics.DrawImage(Before,ClientRectangle,0,0,Before.Width,Before.Height,GraphicsUnit.Pixel,attr);}}}protected override void Dispose(bool d){if(d){timer.Dispose();if(Before!=null)Before.Dispose();if(After!=null)After.Dispose();}base.Dispose(d);}
}
